import{_ as a,a as r,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"PowerShell：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","frontmatter":{"title":"PowerShell：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","showdocs":{"topics":[{"id":"powershell","title":"PowerShell","link":"/topics/powershell/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"PowerShell对象与任务理论课程","summary":"把维护动作、症状调查和同一故障场景的验收放在一起。","status":"active","related":[{"title":"PowerShell：编写 CSV 校验与汇总任务","link":"/systems/shell-automation/powershell/plus/practice/application","kind":"完整实践","scope":"general","audience":"general"},{"title":"PowerShell：基础对象与机制","link":"/systems/shell-automation/powershell/objects-and-streams","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"PowerShell：编写 CSV 校验与汇总任务","link":"/systems/shell-automation/powershell/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PowerShell：编写 CSV 校验与汇总任务","link":"/systems/shell-automation/powershell/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/shell-automation/powershell/operations.md","filePath":"systems/shell-automation/powershell/operations.md"}'),l={name:"systems/shell-automation/powershell/operations.md"};function s(i,e,p,n,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="powershell-发布、排障与恢复练习" tabindex="-1">PowerShell：发布、排障与恢复练习 <a class="header-anchor" href="#powershell-发布、排障与恢复练习" aria-label="Permalink to &quot;PowerShell：发布、排障与恢复练习&quot;">​</a></h1><h2 id="part-1" tabindex="-1">脚本发布、编码与恢复 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;脚本发布、编码与恢复 {#part-1}&quot;">​</a></h2><p>维护PowerShell CSV 汇总前先保存PowerShell 7.4、UTF-8 category/count 输入与对象管道，恢复后以字段校验、错误流、退出码和 Category/Total 对象验收。具体配置见<a href="/systems/shell-automation/powershell/plus/practice/application#source">配套示例</a>。</p><p>教学版本族：PowerShell 7.4 与 .NET 8 语义；Windows PowerShell 5.1 不获得编码、原生命令传参与模块兼容保证。核对日期2026-10-17，不称为2026最新版。示例未执行，配置与命令需按目标环境验收。</p><h3 id="part-1-modules" tabindex="-1">模块与执行策略边界 <a class="header-anchor" href="#part-1-modules" aria-label="Permalink to &quot;模块与执行策略边界 {#part-1-modules}&quot;">​</a></h3><p>PowerShell 模块应固定来源与版本并先审阅导出命令，本例依赖内置 Microsoft.PowerShell.Utility/Management。执行策略影响脚本加载体验，不是完整安全边界；不为运行样例建议全局 Bypass 或 Unrestricted。受组织策略约束时改用获准签名/交付流程，本文不更改策略。</p><h3 id="part-1-recovery" tabindex="-1">输出原子性与恢复 <a class="header-anchor" href="#part-1-recovery" aria-label="Permalink to &quot;输出原子性与恢复 {#part-1-recovery}&quot;">​</a></h3><p>PowerShell 输出恢复要区分内存对象成功和文件提交成功。管道接收方可能在前几个对象后失败，所以不能把“脚本先校验”当作端到端原子提交。需要文件产物时由调用层在受控目录写临时文件、核对退出码后发布，并约定重名覆盖；本例不写文件也不注册任务。</p><h3 id="part-1-cleanup" tabindex="-1">精确清理与编码 <a class="header-anchor" href="#part-1-cleanup" aria-label="Permalink to &quot;精确清理与编码 {#part-1-cleanup}&quot;">​</a></h3><p>PowerShell 清理只涉及用户复制的 CSV 和自行保存的输出。先确认绝对路径，再用 LiteralPath 删除确切文件，不把通配符和递归删除混合。UTF-8无BOM与带BOM、5.1默认输出编码有差异，应在持久化边界显式选编码；课程输入为UTF-8 ASCII子集，源码不自动改写原输入。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-1-exercise}&quot;">​</a></h3><p>题目：good.csv被汇总成功，调用者需要保存CSV并再次显示表格；还收到“脚本被组织执行策略阻止”的另一份记录。应在哪里选择编码与格式化，是否应全局改Bypass重试？</p><p>参考解答：对汇总对象先用明确UTF-8编码导出，保留原业务字段；显示分支再Format-Table，不把显示指令作为保存数据。组织策略阻止发生在业务校验前，应遵循获准签名或交付流程，不全局改Bypass，也不能把该记录算作负数输入拒绝成功。示例未修改系统，恢复只涉及自行保存的确切产物。</p><h3 id="part-1-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;核对资料 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-gb/powershell/module/microsoft.powershell.core/about/about_pipelines?view=powershell-7.4" target="_blank" rel="noopener noreferrer">Microsoft 对象管道</a></li><li><a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_quoting_rules?view=powershell-7.4" target="_blank" rel="noopener noreferrer">Microsoft 引用规则</a></li><li><a href="https://learn.microsoft.com/zh-cn/powershell/module/microsoft.powershell.core/about/about_pipelines?view=powershell-7.4" target="_blank" rel="noopener noreferrer">Microsoft 中文对象管道</a></li></ul><h2 id="part-2" tabindex="-1">参数、非终止错误与退出码排障 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;参数、非终止错误与退出码排障 {#part-2}&quot;">​</a></h2><p>本节沿字段校验、错误流、退出码和 Category/Total 对象定位失败层；先确认PowerShell 7.4、UTF-8 category/count 输入与对象管道，与<a href="/systems/shell-automation/powershell/plus/practice/application#source">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-property" tabindex="-1">属性不存在与格式化 <a class="header-anchor" href="#part-2-property" aria-label="Permalink to &quot;属性不存在与格式化 {#part-2-property}&quot;">​</a></h3><p>PowerShell 属性不存在先用 Get-Member 看实际对象类型，再核对是否提前 Format-Table 或来自原生文本。不要改列名碰运气；把对象、CSV字符串与格式指令分开。本例严格模式让错误属性更早失败，不把 null 默认为正常数据。</p><h3 id="part-2-native" tabindex="-1">原生命令状态与重定向 <a class="header-anchor" href="#part-2-native" aria-label="Permalink to &quot;原生命令状态与重定向 {#part-2-native}&quot;">​</a></h3><p>PowerShell 原生命令失败要检查退出码和 stderr，<code>$?</code> 只代表最近操作状态；随后执行别的命令可能覆盖观察。本例刻意不用外部程序，避免跨平台参数转义和编码牵扯；日后加入原生命令时应单独定义成功码、参数与输出协议。</p><h3 id="part-2-policy" tabindex="-1">脚本加载与数据失败 <a class="header-anchor" href="#part-2-policy" aria-label="Permalink to &quot;脚本加载与数据失败 {#part-2-policy}&quot;">​</a></h3><p>PowerShell 脚本加载被策略阻止发生在业务校验之前，不能把它计为 CSV 拒绝路径通过。分开记录签名/策略错误、参数绑定错误与输入验证错误。不要执行未经审查的远程脚本绕过限制。</p><h3 id="part-2-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-2-exercise}&quot;">​</a></h3><p>题目：Import-Csv读入一行category=alpha、count=-1，另一次管道先Format-Table后尝试访问Category，得到属性不存在。前者为何返回2，后者为何不能靠加一列空Category“修复”？</p><p>参考解答：负数字符串不符合示例允许的十进制非负整数字段，属于已定义输入拒绝，退出2且不输出汇总。第二个问题是数据类型已被格式化转换，应回到格式化之前的业务对象链检查Get-Member，而非伪造空属性掩盖错误；补空列会损失真实分类。两个故障分别在字段校验与对象链路，不能混为CSV文件损坏。</p><h3 id="part-2-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-2-sources" aria-label="Permalink to &quot;核对资料 {#part-2-sources}&quot;">​</a></h3><p>本节沿用<a href="#part-1-sources">本页资料与示例入口</a>。</p><h2 id="part-3" tabindex="-1">任务显示成功却缺少数据的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;任务显示成功却缺少数据的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将PowerShell CSV 汇总的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/shell-automation/powershell/plus/practice/application#source">配套示例</a>中的PowerShell 7.4、UTF-8 category/count 输入与对象管道。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>任务记录为成功，但汇总文件少了一部分数据，日志中出现非终止错误。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>核对执行的是 PowerShell 7 还是 Windows PowerShell 5.1，并保存任务参数与输入编码。</li><li>检查每个输入读取与转换阶段的 ErrorRecord；确认需要中止的 cmdlet 错误是否按约定转为终止错误并被处理。</li><li>对原生程序另查其退出码；检查 Write-Output 是否把调试文字混入了业务对象流。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>使关键失败中止产物提交，通过独立诊断流保留原因；显式处理原生程序的失败状态，不将部分结果覆盖正式汇总。</p><p>验收：正常输入仅输出约定对象；缺失文件、非法 CSV 与原生命令失败都返回约定状态。确认任务退出码、输出条数与文件内容一致。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_error_handling?view=powershell-7.4" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-reasoning" tabindex="-1">对象链路自检 <a class="header-anchor" href="#part-3-reasoning" aria-label="Permalink to &quot;对象链路自检 {#part-3-reasoning}&quot;">​</a></h3><p>解释从 CSV 字节到字符串字段、校验后的 long、分组对象、格式化显示四个阶段。每个阶段的数据类型和错误不同，显示“5”并不能证明原值是整数5。没有业务校验的类型转换无法承担输入契约。</p><h3 id="part-3-exercise" tabindex="-1">独立边界练习 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;独立边界练习 {#part-3-exercise}&quot;">​</a></h3><p>不运行脚本，推演空CSV、多余字段、负数、单行和1001行输入。再写出将结果导出CSV时应该放在哪个阶段，以及为什么记录错误信息不能通过 Write-Output 混入结果。</p><h3 id="part-3-answers" tabindex="-1">参考解答与范围 <a class="header-anchor" href="#part-3-answers" aria-label="Permalink to &quot;参考解答与范围 {#part-3-answers}&quot;">​</a></h3><p>空表、多余字段、负数和超限行数均拒绝；一行仍是数组并可聚合；在汇总对象阶段导出，格式化只放显示末端。错误用错误流并明确非零退出。本课不覆盖远程管理、DSC、云SDK；Windows系统对象与跨平台自动化分别走独立入口。</p><h3 id="part-3-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;核对资料 {#part-3-sources}&quot;">​</a></h3><p>本节沿用<a href="#part-1-sources">本页资料与示例入口</a>。</p>',47)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
